    if d == \"up\":
        lanes = [[(c, r) for r in range(SIZE)] for c in range(SIZE)]
    else:
        lanes = [[(c, r) for r in range(SIZE-1, -1, -1)] for c in range(SIZE)]
    print(f\"=== {d} ===\")
    for lane in lanes:
        print([g.board[r][c] for r, c in lane])
